mapper.select:
SELECT  FROM preparation_task WHERE owner_id=#{owner}
AND status=#{status}
AND target_item_id=#{targetId}
AND planned_date >= #{from} AND planned_date <= #{to}
AND id > #{cursor}
ORDER BY id LIMIT #{limit}

SELECT owner_id,task_id,revision,action,snapshot_json,created_at FROM preparation_task_history
WHERE owner_id=#{owner} AND task_id=#{id}
AND revision < #{before}
ORDER BY revision DESC LIMIT #{limit}

mapper.update:
UPDATE preparation_task SET revision=#{task.revision},title=#{task.title},detail=#{task.detail},
  minutes=#{task.minutes},planned_date=#{task.plannedDate},zone_id=#{task.zoneId},status=#{task.status},
  started_at=#{task.startedAt},completed_at=#{task.completedAt},updated_at=#{task.updatedAt}
WHERE owner_id=#{task.ownerId} AND id=#{task.id} AND revision=#{expected}
